/* Acceso remoto a repositorios de GitHub (token de acceso personal)   */
/* ------------------------------------------------------------------ */
let bpGhToken = null, bpGhOwner = null, bpGhRepo = null, bpGhBranch = null;

function bpGhStorageGet(keys) {
  return new Promise(res => chrome.storage.local.get(keys, res));
}
function bpGhStorageSet(obj) {
  return new Promise(res => chrome.storage.local.set(obj, res));
}
function bpGhStorageRemove(keys) {
  return new Promise(res => chrome.storage.local.remove(keys, res));
}
function bpGhSetActive(flag) {
  return bpGhStorageSet({ gh_active: !!flag });
}

function bpGhB64EncodeUtf8(str) {
  let bytes = new TextEncoder().encode(str), bin = "";
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}
function bpGhB64DecodeUtf8(b64) {
  let bin = atob(b64.replace(/\n/g, "")), bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder("utf-8").decode(bytes);
}
function bpGhEncodePath(path) {
  return path.split("/").map(encodeURIComponent).join("/");
}

async function bpGhApi(path, opts = {}) {
  let headers = Object.assign({
    "Accept": "application/vnd.github+json",
    "X-GitHub-Api-Version": "2022-11-28"
  }, opts.headers || {});
  if (bpGhToken) headers["Authorization"] = `Bearer ${bpGhToken}`;
  let ctrl = new AbortController(), timer = setTimeout(() => ctrl.abort(), 20000), res;
  try {
    res = await fetch(`https://api.github.com${path}`, Object.assign({}, opts, { headers, signal: ctrl.signal }));
  } catch (e) {
    if (e.name === "AbortError") throw new Error("GitHub: tiempo de espera agotado. Comprueba tu conexi\xF3n a internet o si un proxy/cortafuegos est\xE1 bloqueando el acceso a api.github.com.");
    throw new Error(`GitHub: no se pudo conectar (${e.message}).`);
  } finally {
    clearTimeout(timer);
  }
  if (!res.ok) {
    let body = await res.json().catch(() => ({}));
    let msg = body && body.message ? body.message : res.statusText;
    if (res.status === 401) msg = "Token inv\u00E1lido o sin permisos suficientes.";
    if (res.status === 404) msg = "Repositorio, rama o archivo no encontrado (revisa el nombre y los permisos del token).";
    throw new Error(`GitHub: ${msg}`);
  }
  if (res.status === 204) return null;
  return res.json();
}

function bpGhSortChildren(node) {
  if (!node.children) return;
  node.children.sort((a, b) => a.kind !== b.kind
    ? (a.kind === "directory" ? -1 : 1)
    : a.name.localeCompare(b.name, "es", { sensitivity: "base" }));
  node.children.forEach(bpGhSortChildren);
}

async function bpGhOpenRepoTree() {
  let treeRes = await bpGhApi(`/repos/${bpGhOwner}/${bpGhRepo}/git/trees/${encodeURIComponent(bpGhBranch)}?recursive=1`);
  let rootHandle = { __gh: true, owner: bpGhOwner, repo: bpGhRepo, branch: bpGhBranch, path: "", sha: null };
  wr = c2(rootHandle, "directory", `GH: ${bpGhOwner}/${bpGhRepo}`, 0, null);
  wr.expanded = true;
  wr.children = [];
  let nodeByPath = new Map();
  nodeByPath.set("", wr);
  let entries = (treeRes.tree || []).slice().sort((a, b) => a.path.split("/").length - b.path.split("/").length);
  for (let entry of entries) {
    if (entry.type !== "blob" && entry.type !== "tree") continue;
    let parts = entry.path.split("/");
    let name = parts[parts.length - 1];
    let parentPath = parts.slice(0, -1).join("/");
    let parent = nodeByPath.get(parentPath) || wr;
    let kind = entry.type === "tree" ? "directory" : "file";
    let handle = { __gh: true, owner: bpGhOwner, repo: bpGhRepo, branch: bpGhBranch, path: entry.path, sha: entry.sha };
    let node = c2(handle, kind, name, parent.depth + 1, parent);
    if (kind === "directory") { node.children = []; node.expanded = false; nodeByPath.set(entry.path, node); }
    parent.children.push(node);
  }
  bpGhSortChildren(wr);
  bpGhTreeCache = { owner: bpGhOwner, repo: bpGhRepo, branch: bpGhBranch, entries: entries };
  rp();
  if (treeRes.truncated) xo('\u26A0 El repositorio es muy grande: puede que no se muestren todos los archivos.');
}

async function bpGhTryRestore() {
  try {
    let st = await bpGhStorageGet(["gh_token", "gh_owner", "gh_repo", "gh_branch", "gh_active"]);
    if (st.gh_active && st.gh_token && st.gh_owner && st.gh_repo) {
      bpGhToken = st.gh_token; bpGhOwner = st.gh_owner; bpGhRepo = st.gh_repo; bpGhBranch = st.gh_branch;
      await bpGhOpenRepoTree();
      return;
    }
  } catch (e) {
    console.error("No se pudo restaurar la conexi\u00F3n de GitHub", e);
  }
  gq();
}










async function bpGhConnectAndOpen(token, ownerRepoStr, branch) {
  let cleaned = ownerRepoStr.trim().replace(/^https?:\/\/github\.com\//i, "").replace(/\.git$/i, "").replace(/^\/+|\/+$/g, "");
  let parts = cleaned.split("/").filter(Boolean);
  if (parts.length < 2) throw new Error("Escribe el repositorio como usuario/repositorio.");
  let owner = parts[0], repo = parts[1];
  bpGhToken = token.trim();
  bpGhOwner = owner; bpGhRepo = repo;
  let info = await bpGhApi(`/repos/${owner}/${repo}`);
  bpGhBranch = (branch && branch.trim()) || info.default_branch;
  await bpGhStorageSet({ gh_token: bpGhToken, gh_owner: owner, gh_repo: repo, gh_branch: bpGhBranch });
  await bpGhOpenRepoTree();
  await bpGhSetActive(true);
}

async function bpCloseExplorerRoot() {
  if (wr && wr.handle && wr.handle.__gh) {
    wr = null;
    await bpGhSetActive(false);
    gq();
  } else {
    await E0e();
  }
}

