async function bpGhDeleteTreePrefix(owner, repo, branch, prefix) {
  let refData = await bpGhApi(`/repos/${owner}/${repo}/git/ref/heads/${encodeURIComponent(branch)}`);
  let commitSha = refData.object.sha;
  let commitData = await bpGhApi(`/repos/${owner}/${repo}/git/commits/${commitSha}`);
  let baseTreeSha = commitData.tree.sha;
  let fullTree = await bpGhApi(`/repos/${owner}/${repo}/git/trees/${baseTreeSha}?recursive=1`);
  let keepBlobs = (fullTree.tree || []).filter(e => e.type === "blob" && e.path !== prefix && !e.path.startsWith(prefix + "/"));
  let newTree = keepBlobs.map(e => ({ path: e.path, mode: e.mode, type: "blob", sha: e.sha }));
  let treeRes = await bpGhApi(`/repos/${owner}/${repo}/git/trees`, {
    method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ tree: newTree })
  });
  let commitRes = await bpGhApi(`/repos/${owner}/${repo}/git/commits`, {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ message: `Eliminar ${prefix} desde BubiPad`, tree: treeRes.sha, parents: [commitSha] })
  });
  await bpGhApi(`/repos/${owner}/${repo}/git/refs/heads/${encodeURIComponent(branch)}`, {
    method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ sha: commitRes.sha })
  });
}

