let bpGhBtn = document.getElementById("github-btn");
let bpGhPopup = document.getElementById("github-popup");
let bpGhStatusEl = document.getElementById("github-status-text");
let bpGhTokenInput = document.getElementById("github-token-input");
let bpGhRepoInput = document.getElementById("github-repo-input");
let bpGhBranchInput = document.getElementById("github-branch-input");
let bpGhConnectBtn = document.getElementById("github-connect-btn");
let bpGhForgetBtn = document.getElementById("github-forget-btn");

async function bpGhRefreshPopup() {
  let st = await bpGhStorageGet(["gh_token", "gh_owner", "gh_repo", "gh_branch", "gh_active"]);
  if (st.gh_owner && st.gh_repo) {
    bpGhTokenInput.value = st.gh_token || "";
    bpGhRepoInput.value = `${st.gh_owner}/${st.gh_repo}`;
    bpGhBranchInput.value = st.gh_branch || "";
    bpGhStatusEl.textContent = st.gh_active
      ? `Conectado a ${st.gh_owner}/${st.gh_repo}`
      : `Credenciales guardadas para ${st.gh_owner}/${st.gh_repo} (no conectado)`;
    bpGhForgetBtn.style.display = "block";
  } else {
    bpGhStatusEl.textContent = "Sin conectar";
    bpGhForgetBtn.style.display = "none";
  }
}

function bpGhTogglePopup() {
  if (bpGhPopup.style.display === "block") { bpGhPopup.style.display = "none"; return; }
  let rect = bpGhBtn.getBoundingClientRect();
  bpGhPopup.style.top = `${rect.bottom + 4}px`;
  bpGhPopup.style.left = `${Math.min(rect.left, window.innerWidth - 266)}px`;
  bpGhPopup.style.display = "block";
  bpGhRefreshPopup();
}

bpGhBtn.addEventListener("click", bpGhTogglePopup);
document.addEventListener("click", o => {
  if (bpGhPopup.style.display === "block" && !bpGhPopup.contains(o.target) && !bpGhBtn.contains(o.target)) {
    bpGhPopup.style.display = "none";
  }
});

bpGhConnectBtn.addEventListener("click", async () => {
  let token = bpGhTokenInput.value, repoStr = bpGhRepoInput.value, branch = bpGhBranchInput.value;
  if (!token.trim() || !repoStr.trim()) {
    bpGhStatusEl.textContent = "Escribe un token y el repositorio (usuario/repositorio).";
    return;
  }
  bpGhStatusEl.textContent = "Conectando\u2026";
  try {
    await bpGhConnectAndOpen(token, repoStr, branch);
    document.getElementById("sidebar").classList.remove("hidden");
    document.getElementById("sidebar-toggle-btn").classList.remove("active");
    bpGhPopup.style.display = "none";
    xo(`Repositorio "${bpGhOwner}/${bpGhRepo}" abierto`);
  } catch (e) {
    bpGhStatusEl.textContent = `\u26A0 ${e.message}`;
  }
});

bpGhForgetBtn.addEventListener("click", async () => {
  await bpGhStorageRemove(["gh_token", "gh_owner", "gh_repo", "gh_branch", "gh_active"]);
  bpGhToken = null; bpGhOwner = null; bpGhRepo = null; bpGhBranch = null;
  if (wr && wr.handle && wr.handle.__gh) { wr = null; gq(); }
  bpGhTokenInput.value = ""; bpGhRepoInput.value = ""; bpGhBranchInput.value = "";
  bpGhRefreshPopup();
});

/* ------------------------------------------------------------------ */
/* Inserci\u00F3n de caracteres Unicode mediante c\u00F3digo (Alt+X, estilo Word) */
/* ------------------------------------------------------------------ */
function bpUnicodeLastCodePoint(str) {
  if (!str) return null;
  let last = str.charCodeAt(str.length - 1);
  if (last >= 0xDC00 && last <= 0xDFFF && str.length >= 2) {
    let prev = str.charCodeAt(str.length - 2);
    if (prev >= 0xD800 && prev <= 0xDBFF) {
      let cp = (prev - 0xD800) * 0x400 + (last - 0xDC00) + 0x10000;
      return { codePoint: cp, units: 2 };
    }
  }
  return { codePoint: last, units: 1 };
}

function bpUnicodeApplyEdit(startLine, startCol, endLine, endCol, text) {
  Nt.executeEdits("unicode-toggle", [{
    range: { startLineNumber: startLine, startColumn: startCol, endLineNumber: endLine, endColumn: endCol },
    text
  }]);
  let model = Nt.getModel();
  let startOffset = model.getOffsetAt({ lineNumber: startLine, column: startCol });
  let endPos = model.getPositionAt(startOffset + text.length);
  Nt.setSelection(new DF(endPos.lineNumber, endPos.column, endPos.lineNumber, endPos.column));
  Nt.focus();
}

function bpUnicodeIsValidCodePoint(cp) {
  return !isNaN(cp) && cp >= 0 && cp <= 0x10FFFF && !(cp >= 0xD800 && cp <= 0xDFFF);
}

function bpUnicodeToggle() {
  let model = Nt.getModel();
  if (!model) return;
  let sel = Nt.getSelection();
  if (sel && !sel.isEmpty()) {
    let text = model.getValueInRange(sel);
    if (/^[0-9a-fA-F]{1,6}$/.test(text)) {
      let cp = parseInt(text, 16);
      if (!bpUnicodeIsValidCodePoint(cp)) {
        xo(`\u26A0 "${text}" no es un c\u00F3digo Unicode v\u00E1lido`);
        return;
      }
      bpUnicodeApplyEdit(sel.startLineNumber, sel.startColumn, sel.endLineNumber, sel.endColumn, String.fromCodePoint(cp));
      xo(`Insertado car\u00E1cter U+${cp.toString(16).toUpperCase().padStart(4, "0")}`);
      return;
    }
    let chars = Array.from(text);
    if (chars.length === 1) {
      let hex = chars[0].codePointAt(0).toString(16).toUpperCase().padStart(4, "0");
      bpUnicodeApplyEdit(sel.startLineNumber, sel.startColumn, sel.endLineNumber, sel.endColumn, hex);
      xo(`C\u00F3digo Unicode: U+${hex}`);
      return;
    }
    xo("\u26A0 Selecciona un c\u00F3digo hexadecimal o un solo car\u00E1cter para convertir");
    return;
  }
  let pos = Nt.getPosition();
  if (!pos) return;
  let lineContent = model.getLineContent(pos.lineNumber);
  let before = lineContent.slice(0, pos.column - 1);
  let m = before.match(/[0-9a-fA-F]{1,6}$/);
  if (m) {
    let hex = m[0];
    let cp = parseInt(hex, 16);
    if (!bpUnicodeIsValidCodePoint(cp)) {
      xo(`\u26A0 "${hex}" no es un c\u00F3digo Unicode v\u00E1lido`);
      return;
    }
    bpUnicodeApplyEdit(pos.lineNumber, pos.column - hex.length, pos.lineNumber, pos.column, String.fromCodePoint(cp));
    xo(`Insertado car\u00E1cter U+${cp.toString(16).toUpperCase().padStart(4, "0")}`);
    return;
  }
  let info = bpUnicodeLastCodePoint(before);
  if (info) {
    let hex = info.codePoint.toString(16).toUpperCase().padStart(4, "0");
    bpUnicodeApplyEdit(pos.lineNumber, pos.column - info.units, pos.lineNumber, pos.column, hex);
    xo(`C\u00F3digo Unicode: U+${hex}`);
    return;
  }
  xo("\u26A0 Escribe un c\u00F3digo hexadecimal (ej. 1F600) y pulsa Alt+X");
}

Nt.addCommand(ls.Alt | Fa.KeyX, bpUnicodeToggle);

/* ------------------------------------------------------------------ */
/* Navegaci\u00F3n tipo Obsidian en la vista previa (local + GitHub)         */
/* ------------------------------------------------------------------ */
function bpSplitAnchor(raw) {
  let idx = raw.indexOf("#");
  if (idx === -1) return { path: raw, anchor: null };
  return { path: raw.slice(0, idx), anchor: raw.slice(idx + 1) };
}

function bpSlugify(text) {
  return String(text)
    .trim()
    .toLowerCase()
    .replace(/[`*_~\[\]()]/g, "")
    .replace(/[^\p{L}\p{N}\- ]+/gu, "")
    .trim()
    .replace(/\s+/g, "-");
}

function bpScrollToHeading(anchor) {
  if (!anchor) { Iu.scrollTop = 0; return; }
  let slug;
  try { slug = bpSlugify(decodeURIComponent(anchor)); } catch { slug = bpSlugify(anchor); }
  if (!slug) return;
  let el = null;
  try { el = Iu.querySelector(`[id="${CSS.escape(slug)}"]`); } catch {}
  if (el) el.scrollIntoView({ block: "start" });
}

function bpBaseNameMatches(path, nameLower) {
  let base = path.split("/").pop();
  let baseNoExt = base.replace(/\.[^.]+$/, "");
  return base.toLowerCase() === nameLower || baseNoExt.toLowerCase() === nameLower;
}

/* --- Resoluci\u00f3n de rutas relativas -------------------------------- */

function bpGhResolveRelativePath(currentPath, relPath) {
  if (relPath.startsWith("/")) {
    let parts = [];
    for (let seg of relPath.split("/")) {
      if (seg === "" || seg === ".") continue;
      if (seg === "..") { if (parts.length) parts.pop(); continue; }
      parts.push(seg);
    }
    return parts.join("/");
  }
  let baseDir = currentPath.includes("/") ? currentPath.slice(0, currentPath.lastIndexOf("/")) : "";
  let parts = baseDir === "" ? [] : baseDir.split("/");
  for (let seg of relPath.split("/")) {
    if (seg === "" || seg === ".") continue;
    if (seg === "..") {
      if (parts.length === 0) throw new Error("La ruta del enlace sale del repositorio.");
      parts.pop();
    } else parts.push(seg);
  }
  return parts.join("/");
}

async function bpOpenInternalPath(pathPart) {
  let tab = sp();
  if (!tab) throw new Error("No hay ninguna nota abierta.");
  let decoded;
  try { decoded = decodeURIComponent(pathPart); } catch { decoded = pathPart; }
  if (tab.handle && tab.handle.__gh) {
    let fullPath = bpGhResolveRelativePath(tab.handle.path, decoded);
    let handle = { __gh: true, owner: tab.handle.owner, repo: tab.handle.repo, branch: tab.handle.branch, path: fullPath, sha: null };
    await bpGhOpenFile({ name: fullPath.split("/").pop() || fullPath, handle });
  } else if (tab.dirChain) {
    let { fileHandle, dirChain } = await aq(decoded);
    await A2(fileHandle, dirChain);
  } else {
    throw new Error("Este archivo no se abri\u00F3 desde una carpeta, as\u00ED que no s\u00E9 d\u00F3nde buscar enlaces internos. \u00C1brelo desde el explorador (\uD83D\uDCC1) para poder navegar entre notas.");
  }
}

/* --- Wikilinks [[Nota]] al estilo Obsidian ---------------------------- */

let bpGhTreeCache = null;
async function bpGhGetTreeEntries(owner, repo, branch) {
  if (bpGhTreeCache && bpGhTreeCache.owner === owner && bpGhTreeCache.repo === repo && bpGhTreeCache.branch === branch) {
    return bpGhTreeCache.entries;
  }
  let res = await bpGhApi(`/repos/${owner}/${repo}/git/trees/${encodeURIComponent(branch)}?recursive=1`);
  let entries = (res.tree || []).filter(e => e.type === "blob" || e.type === "tree");
  bpGhTreeCache = { owner, repo, branch, entries };
  return entries;
}

async function bpLocalFindFileByName(rootHandle, nameLower) {
  async function walk(dirHandle, chain) {
    for await (let t of dirHandle.values()) {
      if (I0e.has(t.name)) continue;
      if (t.kind === "file") {
        if (bpBaseNameMatches(t.name, nameLower)) return { fileHandle: t, dirChain: chain };
      } else if (t.kind === "directory") {
        let found = await walk(t, [...chain, t]);
        if (found) return found;
      }
    }
    return null;
  }
  return await walk(rootHandle, [rootHandle]);
}

async function bpOpenWikilink(name) {
  let tab = sp();
  if (!tab) throw new Error("No hay ninguna nota abierta.");
  let nameLower = name.toLowerCase();
  if (tab.handle && tab.handle.__gh) {
    let entries = await bpGhGetTreeEntries(tab.handle.owner, tab.handle.repo, tab.handle.branch);
    let match = entries.find(e => e.type === "blob" && bpBaseNameMatches(e.path, nameLower));
    if (!match) throw new Error(`No se encontr\u00F3 ninguna nota llamada "${name}" en el repositorio.`);
    let handle = { __gh: true, owner: tab.handle.owner, repo: tab.handle.repo, branch: tab.handle.branch, path: match.path, sha: match.sha };
    await bpGhOpenFile({ name: match.path.split("/").pop(), handle });
  } else if (tab.dirChain && tab.dirChain[0]) {
    let found = await bpLocalFindFileByName(tab.dirChain[0], nameLower);
    if (!found) throw new Error(`No se encontr\u00F3 ninguna nota llamada "${name}" en la carpeta.`);
    await A2(found.fileHandle, found.dirChain);
  } else {
    throw new Error("Este archivo no se abri\u00F3 desde una carpeta, as\u00ED que no puedo buscar notas por nombre. \u00C1brelo desde el explorador (\uD83D\uDCC1).");
  }
}

/* --- Im\u00e1genes internas (![alt](ruta)) --------------------------------- */

function bpGuessMime(path) {
  let ext = path.split(".").pop().toLowerCase();
  return {
    png: "image/png", jpg: "image/jpeg", jpeg: "image/jpeg", gif: "image/gif",
    svg: "image/svg+xml", webp: "image/webp", bmp: "image/bmp", ico: "image/x-icon"
  }[ext] || "application/octet-stream";
}

function bpShowImageError(img, msg) {
  let span = document.createElement("span");
  span.className = "pv-img-error";
  span.textContent = `\u26A0 ${img.getAttribute("alt") || "imagen"}: ${msg}`;
  img.replaceWith(span);
}

async function bpLoadInternalImage(img, tab, rawTarget) {
  let { path: pathPart } = bpSplitAnchor(rawTarget);
  let decoded;
  try { decoded = decodeURIComponent(pathPart); } catch { decoded = pathPart; }
  try {
    let url;
    if (tab.handle && tab.handle.__gh) {
      let fullPath = bpGhResolveRelativePath(tab.handle.path, decoded);
      let data = await bpGhApi(`/repos/${tab.handle.owner}/${tab.handle.repo}/contents/${bpGhEncodePath(fullPath)}?ref=${encodeURIComponent(tab.handle.branch)}`);
      if (Array.isArray(data) || data.encoding !== "base64") throw new Error("no es un archivo de imagen v\u00E1lido");
      let bin = atob(data.content.replace(/\n/g, "")), bytes = new Uint8Array(bin.length);
      for (let k = 0; k < bin.length; k++) bytes[k] = bin.charCodeAt(k);
      url = URL.createObjectURL(new Blob([bytes], { type: bpGuessMime(fullPath) }));
    } else if (tab.dirChain) {
      let { fileHandle } = await aq(decoded);
      let file = await fileHandle.getFile();
      url = URL.createObjectURL(file);
    } else {
      return;
    }
    img.addEventListener("load", () => setTimeout(() => URL.revokeObjectURL(url), 1000), { once: true });
    img.src = url;
  } catch (e) {
    bpShowImageError(img, e.message);
  }
}

function bpResolveInternalImages(container) {
  let imgs = container.querySelectorAll("img[data-internal-image]");
  if (!imgs.length) return;
  let tab = sp();
  if (!tab) return;
  for (let img of imgs) bpLoadInternalImage(img, tab, img.dataset.internalImage);
}
